package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.File;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Date;
import java.util.List;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ZipArchiveEntry#isUnixSymlink
 */
public class ZipArchiveEntry_isUnixSymlink_TriageGen2Test {

    @Test
    public void testIsUnixSymlink_WhenLinkFlagIsSet() {
        // Arrange
        ZipArchiveEntry entry = new ZipArchiveEntry("test_link");
        // Set the Unix mode to include the LINK_FLAG
        entry.setUnixMode(UnixStat.LINK_FLAG);

        // Act
        boolean result = entry.isUnixSymlink();

        // Assert
        assertTrue("isUnixSymlink should return true when LINK_FLAG is present in Unix mode", result);
    }

    @Test
    public void testIsUnixSymlink_WhenLinkFlagIsNotSet() {
        // Arrange
        ZipArchiveEntry entry = new ZipArchiveEntry("test_file");
        // Set a mode that does not include the LINK_FLAG (e.g., 0 or regular file mode)
        entry.setUnixMode(0);

        // Act
        boolean result = entry.isUnixSymlink();

        // Assert
        assertFalse("isUnixSymlink should return false when LINK_FLAG is not present in Unix mode", result);
    }

    @Test
    public void testIsUnixSymlink_WhenOtherFlagsAreSetButNotLinkFlag() {
        // Arrange
        ZipArchiveEntry entry = new ZipArchiveEntry("test_dir");
        // Set a mode with other bits (e.g., directory bit) but NOT the link bit
        // Assuming UnixStat has other constants, or just using a bitwise combination
        int otherMode = 0100000; // typical directory bit in octal
        entry.setUnixMode(otherMode);

        // Act
        boolean result = entry.isUnixSymlink();

        // Assert
        assertFalse("isUnixSymlink should return false when other flags are set but LINK_FLAG is missing", result);
    }

    @Test
    public void testIsUnixSymlink_WhenBothLinkAndOtherFlagsAreSet() {
        // Arrange
        ZipArchiveEntry entry = new ZipArchiveEntry("test_complex_link");
        // Combine LINK_FLAG with another bit
        int combinedMode = UnixStat.LINK_FLAG | 0100000; 
        entry.setUnixMode(combinedMode);

        // Act
        boolean result = entry.isUnixSymlink();

        // Assert
        assertTrue("isUnixSymlink should return true when LINK_FLAG is present even if other bits are set", result);
    }
}
